package com.printflow.customer;
import com.printflow.identity.StaffPrincipal;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.io.IOException;import java.net.URLDecoder;import java.nio.charset.StandardCharsets;import java.util.UUID;import org.springframework.core.io.InputStreamResource;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/design/enquiries/{id}/fulfilment/photos") public class DeliveryPhotoController {
 public record Policy(boolean required,@NotBlank @Size(min=10,max=500) String note,@AssertTrue boolean confirmed){}
 private final DeliveryPhotos photos;public DeliveryPhotoController(DeliveryPhotos photos){this.photos=photos;}
 @GetMapping public ResponseEntity<?> list(@AuthenticationPrincipal StaffPrincipal u,@PathVariable UUID id){return response(photos.list(u,id));}
 @PostMapping public ResponseEntity<?> upload(@AuthenticationPrincipal StaffPrincipal u,@PathVariable UUID id,@RequestParam String stage,@RequestHeader("X-File-Name") String name,@RequestHeader("X-Photo-Caption") String caption,@RequestHeader("Content-Type") String mime,HttpServletRequest request)throws IOException{if(name.length()>2160||caption.length()>6000)throw new IllegalArgumentException("Photo metadata too long");return ResponseEntity.status(201).cacheControl(CacheControl.noStore()).body(photos.upload(u,id,stage,URLDecoder.decode(name,StandardCharsets.UTF_8),mime,URLDecoder.decode(caption,StandardCharsets.UTF_8),request.getInputStream()));}
 @PostMapping("/policy") public ResponseEntity<?> policy(@AuthenticationPrincipal StaffPrincipal u,@PathVariable UUID id,@Valid @RequestBody Policy input){return response(photos.policy(u,id,input.required(),input.note()));}
 @PostMapping("/{photo}/scan") public ResponseEntity<?> scan(@AuthenticationPrincipal StaffPrincipal u,@PathVariable UUID id,@PathVariable UUID photo)throws IOException{return response(photos.rescan(u,id,photo));}
 @GetMapping("/{photo}/preview") public ResponseEntity<?> preview(@AuthenticationPrincipal StaffPrincipal u,@PathVariable UUID id,@PathVariable UUID photo)throws IOException{var image=photos.preview(u,id,photo);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).contentType(MediaType.parseMediaType(image.mime())).contentLength(image.size()).header("X-Content-Type-Options","nosniff").header("Content-Disposition","inline").header("Content-Security-Policy","sandbox; default-src 'none'").body(new InputStreamResource(image.stream()));}
 private ResponseEntity<?> response(Object body){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(body);}
}
